const $=s=>document.querySelector(s);let lang=new URLSearchParams(location.search).get('lang');if(!CONTENT[lang]){try{lang=localStorage.getItem('easyoil-language')}catch{}}if(!CONTENT[lang])lang='fr';
const ids=['about','business','infrastructure','africa','partners','contact'];const logo=()=>`<a class="brand official-brand" href="#home" aria-label="EASYOIL"><img src="assets/easyoil-logo.png" alt="EASYOIL"></a>`;
const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function render(){const t=CONTENT[lang];document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.title=t.title;$('meta[name="description"]').content=t.description;$('#language').value=lang;document.querySelector('header .brand').outerHTML=logo();$('.skip').textContent=t.skip;$('.close').ariaLabel=t.close;$('#navigation').innerHTML=t.nav.map((n,i)=>`<a href="#${ids[i]}" ${i===5?'class="nav-contact"':''}>${n}</a>`).join('');
$('#main').innerHTML=`
<section class="hero" id="home"><img src="assets/hero.webp" alt="" fetchpriority="high"><div class="wrap reveal"><div class="eyebrow">${t.eyebrow}</div><h1>${t.hero}</h1><p>${t.heroText}</p><div class="actions"><a class="button" href="#business">${t.explore}</a><a class="button outline" href="#contact">${t.partner}</a></div></div><div class="hero-bottom"><span>${t.heroFoot}</span><a href="#about">${t.scroll}</a></div></section>
<div class="ticker"><div class="wrap">${t.ticker.map(x=>`<span>${x}</span>`).join('')}</div></div>
<section class="section" id="about"><div class="wrap two-col"><div><div class="eyebrow">${t.aboutLabel}</div><h2>${t.aboutTitle}</h2><p class="lead">${t.aboutLead}</p><p class="muted">${t.aboutText}</p><div class="overview-lines">${t.aboutLines.map((x,i)=>`<div>${x}<span>0${i+1}</span></div>`).join('')}</div></div><div class="photo-frame"><img src="assets/easyoil-sign.png" loading="lazy" alt="${t.realSign}"><div class="photo-note">${t.realPhoto}</div></div></div></section>
<section class="section paper" id="business"><div class="wrap"><div class="eyebrow">${t.businessLabel}</div><div class="section-heading"><h2>${t.businessTitle}</h2><p>${t.businessText}</p></div><div class="business-grid">${t.business.map((b,i)=>`<article class="business-card"><span class="number">0${i+1} / EASYOIL</span><h3>${b[0]}</h3><p>${b[1]}</p><button class="text-link" data-business="${i}">${t.learn}</button></article>`).join('')}</div></div></section>
<section class="feature real-infrastructure" id="infrastructure"><img src="assets/easyoil-storage.png" loading="lazy" alt=""><div class="wrap"><div class="content"><div class="eyebrow">${t.infraLabel}</div><h2>${t.infraTitle}</h2><p>${t.infraText}</p><div class="feature-tags">${t.infraTags.map(x=>`<span>${x}</span>`).join('')}</div><div class="actions"><a class="button" href="#contact" data-enquiry="1">${t.infraCta}</a></div></div></div></section>
<section class="section" id="trading"><div class="wrap products"><div><div class="eyebrow">${t.tradeLabel}</div><h2>${t.tradeTitle}</h2><p class="muted">${t.tradeText}</p><a class="button dark" href="#contact" data-enquiry="0">${t.enquiry}</a><p class="muted" style="font-size:12px;margin-top:22px">${t.tradeNote}</p></div><div class="product-list">${t.products.map((p,i)=>`<details ${i===0?'open':''}><summary><span>${p[0]}<small class="product-code">${p[1]}</small></span></summary><p>${p[2]}</p></details>`).join('')}</div></div></section>
<section class="section paper" id="logistics"><div class="wrap two-col"><div class="equipment-photo"><img src="assets/easyoil-distribution.png" loading="lazy" alt="${t.logisticsAlt}"><p>${t.realPhoto}</p></div><div><div class="eyebrow">${t.logisticsLabel}</div><h2>${t.logisticsTitle}</h2><p class="muted">${t.logisticsText}</p><div class="overview-lines">${t.logisticsSteps.map((x,i)=>`<div>${x}<span>0${i+1}</span></div>`).join('')}</div></div></div></section><section class="section navy" id="projects"><div class="wrap"><div class="eyebrow">${t.processLabel}</div><div class="section-heading"><h2>${t.processTitle}</h2><p class="muted">${t.processText}</p></div><div class="process">${t.steps.map((x,i)=>`<div><span>0${i+1}</span><h3>${x[0]}</h3><p>${x[1]}</p></div>`).join('')}</div><div class="two-col" style="border-top:1px solid #ffffff25;margin-top:45px;padding-top:35px"><h3 style="font-size:24px">${t.financeTitle}</h3><p class="muted" style="font-size:14px">${t.financeText}</p></div></div></section>
<section class="feature" id="africa"><img src="assets/solar.webp" loading="lazy" alt=""><div class="wrap"><div class="content"><div class="eyebrow">${t.africaLabel}</div><h2>${t.africaTitle}</h2><p>${t.africaText}</p><div class="feature-tags">${t.africaTags.map(x=>`<span>${x}</span>`).join('')}</div></div></div></section>
<section class="section" id="markets"><div class="wrap regions"><div><div class="eyebrow">${t.globalLabel}</div><h2>${t.globalTitle}</h2><div class="region-tabs" role="tablist" aria-label="${t.globalLabel}">${t.regions.map((r,i)=>`<button role="tab" id="region-${i}" aria-controls="region-copy" aria-selected="${i===0}" tabindex="${i===0?0:-1}" class="${i===0?'active':''}" data-region="${i}">${r}</button>`).join('')}</div><p class="region-copy muted" id="region-copy" role="tabpanel" aria-labelledby="region-0">${t.regionTexts[0]}</p></div><div class="corridor"><div class="world-map"><img src="assets/world.svg" alt=""><span class="map-point" style="left:55%;top:55%"></span><span class="map-point" style="left:62%;top:39%"></span><span class="map-point" style="left:53%;top:25%"></span><span class="map-point" style="left:75%;top:33%"></span></div><div class="corridor-label">${t.corridor}</div><strong>${t.corridorA}</strong><div class="connector"></div><strong>${t.corridorB}</strong><p>${t.corridorNote}</p></div></div></section>
<section class="section paper" id="partners"><div class="wrap"><div class="eyebrow">${t.partnersLabel}</div><h2>${t.partnersTitle}</h2><div class="partner-grid">${t.partners.map((p,i)=>`<article class="partner-card"><h3>${p[0]}</h3><p>${p[1]}</p><ul>${p[2].map(v=>`<li>${v}</li>`).join('')}</ul><a class="button dark" href="#contact" data-enquiry="${i===0?2:3}">${p[3]}</a></article>`).join('')}</div></div></section>
<section class="section" id="compliance"><div class="wrap compliance-grid"><div><div class="eyebrow">${t.complianceLabel}</div><h2>${t.complianceTitle}</h2><p class="muted">${t.complianceText}</p><button class="text-link" data-modal="compliance">${t.policy}</button></div><div class="principles">${t.principles.map((p,i)=>`<article><span>0${i+1}</span><h3>${p[0]}</h3><p class="muted">${p[1]}</p></article>`).join('')}</div></div></section>
<section class="section paper" id="insights"><div class="wrap"><div class="eyebrow">${t.insightsLabel}</div><h2>${t.insightsTitle}</h2><div class="insights-grid">${t.insights.map((n,i)=>`<article class="insight"><div class="insight-image"><img src="assets/${['hero','lng','solar'][i]}.webp" loading="lazy" alt=""></div><div class="meta">${n[0]}</div><h3>${n[1]}</h3><p>${n[2]}</p><button class="text-link" data-insight="${i}">${t.read}</button></article>`).join('')}</div></div></section>
<section class="section navy" id="contact"><div class="wrap contact-grid"><div class="contact-aside"><div class="eyebrow">${t.contactLabel}</div><h2>${t.contactTitle}</h2><p>${t.contactText}</p><div class="contact-facts">${t.contactFact}</div></div><form id="enquiry-form"><div class="form-grid"><label class="field full">${t.form.type}<select name="type" id="enquiry-type">${t.form.types.map((n,i)=>`<option value="${i}">${n}</option>`).join('')}</select></label>${field('name',t.form.name,'text',true,'name')}${field('company',t.form.company,'text',true,'organization')}${field('email',t.form.email,'email',true,'email')}${field('country',t.form.country,'text',true,'country-name')}<div class="trade-fields" id="trade-fields"><label class="field">${t.form.product}<select name="product"><option value="">${t.form.choose}</option>${t.products.map(p=>`<option>${p[0]}</option>`).join('')}</select></label>${field('spec',t.form.spec)}${field('quantity',t.form.quantity)}${field('destination',t.form.destination)}<label class="field">${t.form.incoterm}<select name="incoterm"><option value="">${t.form.choose}</option><option>FOB</option><option>CIF</option><option>CFR</option><option>DAP</option><option>FCA</option></select></label>${field('schedule',t.form.schedule)}</div><label class="field full">${t.form.message}<textarea name="message" required maxlength="5000"></textarea></label><label class="check-label full"><input type="checkbox" required>${t.form.consent}</label></div><p class="form-note">${t.form.note}</p><button class="button" type="submit">${t.form.submit}</button><div class="form-feedback" role="status"></div></form></div></section>`;
$('#footer').innerHTML=`<div class="footer-main"><div>${logo()}<p>${t.footerText}</p></div><div class="footer-links">${t.nav.map((x,i)=>`<a href="#${ids[i]}">${x}</a>`).join('')}<a href="#compliance">${t.policy}</a><a href="#insights">${t.insightsLabel.slice(5)}</a></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} EASYOIL. ${t.rights}</span><span>${t.imageDisclaimer}</span><span><button data-modal="privacy">${t.privacy}</button> · <button data-modal="legal">${t.legal}</button></span></div>`;
bind();}
function field(name,label,type='text',required=false,autocomplete='off'){return `<label class="field">${label}<input name="${name}" type="${type}" ${required?'required':''} autocomplete="${autocomplete}" maxlength="200"></label>`}
function showModal(title,body){$('#detail-body').innerHTML=`<h2>${title}</h2>${body}`;$('#detail').showModal()}
function bind(){const t=CONTENT[lang];document.querySelectorAll('[data-business]').forEach(b=>b.onclick=()=>{const v=t.business[+b.dataset.business];showModal(v[0],`<p class="lead">${v[1]}</p><p>${v[3]}</p><p>${v[2]}</p><a class="button dark" href="#contact" onclick="document.querySelector('#detail').close()">${t.partner}</a>`)});document.querySelectorAll('[data-insight]').forEach(b=>b.onclick=()=>{const n=t.insights[+b.dataset.insight];showModal(n[1],n[3].map(p=>`<p>${p}</p>`).join(''))});document.querySelectorAll('[data-modal]').forEach(b=>b.onclick=()=>{const k=b.dataset.modal;showModal(k==='compliance'?t.policy:t[k+'Title'],`<p>${t[k+'Body']}</p>`)});document.querySelectorAll('[data-region]').forEach(b=>{b.onclick=()=>selectRegion(+b.dataset.region);b.onkeydown=e=>{let i=+b.dataset.region;if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();i=(i+(e.key==='ArrowRight'?1:3))%4;selectRegion(i);$(`#region-${i}`).focus()}if(e.key==='Home'||e.key==='End'){e.preventDefault();i=e.key==='Home'?0:3;selectRegion(i);$(`#region-${i}`).focus()}}});document.querySelectorAll('[data-enquiry]').forEach(a=>a.onclick=()=>{$('#enquiry-type').value=a.dataset.enquiry;toggleTrade()});$('#enquiry-type').onchange=toggleTrade;$('#enquiry-form').onsubmit=e=>{e.preventDefault();const data=new FormData(e.currentTarget);const lines=[t.downloadTitle,'',t.form.type+': '+t.form.types[+data.get('type')]];for(const [key,value]of data){if(key!=='type'&&value)lines.push((t.form[key]||key)+': '+value)}const blob=new Blob(['\uFEFF'+lines.join('\n')],{type:'text/plain;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`EASYOIL-${lang}-${new Date().toISOString().slice(0,10)}.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('.form-feedback').textContent=t.form.success};document.querySelectorAll('a[href^="#"]').forEach(a=>a.addEventListener('click',()=>{$('#navigation').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false')}));}
function selectRegion(i){document.querySelectorAll('.map-point').forEach((p,n)=>p.classList.toggle('active',n===i));document.querySelectorAll('[data-region]').forEach(b=>{const active=+b.dataset.region===i;b.classList.toggle('active',active);b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1});$('#region-copy').textContent=CONTENT[lang].regionTexts[i];$('#region-copy').setAttribute('aria-labelledby',`region-${i}`)}
function toggleTrade(){const hidden=$('#enquiry-type').value!=='0';$('#trade-fields').hidden=hidden;$('#trade-fields').querySelectorAll('input,select').forEach(el=>el.disabled=hidden)}
$('#language').onchange=e=>{lang=e.target.value;try{localStorage.setItem('easyoil-language',lang)}catch{}const url=new URL(location.href);url.searchParams.set('lang',lang);history.replaceState(null,'',url);render()};$('.menu-toggle').onclick=()=>{const open=$('#navigation').classList.toggle('open');$('.menu-toggle').setAttribute('aria-expanded',String(open))};$('.close').onclick=()=>$('#detail').close();$('#detail').onclick=e=>{if(e.target===$('#detail')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}};document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#navigation').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false')}});render();

